test('createInvoice accepts 0% and 100% discount', () => {
  const r0 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1, discountPercent: 0 }],
