test('lineDiscount calculates discount as lineTotal * discountPercent / 100', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 1000, discountPercent: 10 }), 1000);
  assert.equal(lineDiscount({ qty: 5, unitPrice: 1000, discountPercent: 50 }), 2500);
  assert.equal(lineDiscount({ qty: 2, unitPrice: 1000, discountPercent: 25 }), 500);
});

test('lineDiscount defaults to 0% when discountPercent not provided', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 1000 }), 0);
});

test('lineDiscount with decimal percentage', () => {
  assert.equal(lineDiscount({ qty: 100, unitPrice: 1000, discountPercent: 12.5 }), 12500);
});

test('lineDiscount clamps to 0', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 1000, discountPercent: -10 }), 0);
});

test('invoiceTotals returns discount field', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 10 }],
  }).value;

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 47500);
  assert.equal(totals.discount, 4750);
  assert.equal(totals.total, 42750);
});

test('invoiceTotals sums discounts from multiple lines', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'COPY-HOUR', qty: 3, discountPercent: 20 },
    ],
  }).value;

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 5 * 9500 + 3 * 6000);
  assert.equal(totals.discount, 4750 + 3600);
  assert.equal(totals.total, totals.subtotal - totals.discount);
});

test('invoiceTotals with 0% discount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 0 }],
